extra_head_css:
.upscale-workspace { display: flex; gap: 24px; flex-wrap: wrap; }
    .upscale-sidebar { flex: 0 0 280px; display: flex; flex-direction: column; gap: 16px; }
    .upscale-canvas-area { flex: 1; min-width: 300px; }

    .scale-btns { display: flex; gap: 8px; }
    .scale-btn {
      flex: 1; padding: 10px 8px; border: 2px solid var(--border); border-radius: 8px;
      background: var(--bg-primary); color: var(--text-secondary); cursor: pointer;
      text-align: center; font-size: .85rem; font-weight: 600; transition: all .2s;
    }
    .scale-btn:hover { border-color: var(--accent); color: var(--text-primary); }
    .scale-btn.active { border-color: var(--accent); background: rgba(99,102,241,.1); color: var(--accent); }

    .control-group { display: flex; flex-direction: column; gap: 6px; }
    .control-group label { font-size: .8rem; color: var(--text-secondary); font-weight: 500; }
    .control-group select {
      padding: 8px 10px; border: 1px solid var(--border); border-radius: 6px;
      background: var(--bg-primary); color: var(--text-primary); font-size: .85rem;
    }
    .control-group input[type="range"] { width: 100%; }

    .dim-info {
      background: var(--bg-secondary); border: 1px solid var(--border); border-radius: 8px;
      padding: 12px; font-size: .85rem;
    }
    .dim-info .dim-row { display: flex; justify-content: space-between; margin-bottom: 4px; }
    .dim-info .dim-row:last-child { margin-bottom: 0; }
    .dim-info .dim-label { color: var(--text-secondary); }
    .dim-info .dim-value { color: var(--text-primary); font-weight: 500; }
    .dim-info .dim-new { color: var(--accent); font-weight: 600; }

    .canvas-wrapper {
      background: repeating-conic-gradient(var(--bg-secondary) 0% 25%, var(--bg-primary) 0% 50%) 50% / 20px 20px;
      border: 1px solid var(--border); border-radius: 12px; padding: 16px;
      display: flex; align-items: center; justify-content: center; min-height: 300px;
      overflow: auto;
    }
    .canvas-wrapper canvas { max-width: 100%; max-height: 500px; border-radius: 4px; }

    @media (max-width: 768px) {
      .upscale-workspace { flex-direction: column; }
      .upscale-sidebar { flex: none; width: 100%; }
    }
